INSERT OR IGNORE INTO website_pages (id, site, slug, title, description, nav, hide_nav, position, draft, rev, updated_at) VALUES ('pg-m-privacy', 'monarch', 'privacy', 'Privacy Policy', 'How Monarch Tax Suite collects, uses, protects and shares information, including text messaging.', 0, 0, 20, '[{"id":"msec-000m","type":"hero","eyebrow":"Privacy Policy","title":"Your information, handled with care.","body":"How Monarch Tax Suite collects, uses, protects and shares personal information — on our website, during setup, and by email and text.\n\nEffective November 12, 2026"},{"id":"msec-000n","type":"cards","tone":"light","columns":2,"items":[{"title":"Who we are","body":"Monarch Tax Suite (“Monarch,” “we,” “us”) provides tax software, business systems, onboarding and mentorship to tax professionals and tax offices. You can reach us at info@monarchtaxsuite.com."},{"title":"Information we collect","body":"• Information you give us on our website: your name, office name, email, phone number, city and state, and anything you write in a form — including answers you give in our free WISP generator.\n• Information you give us to set up your services, through a private setup link: office details, preparer and location information, and documents needed for software and bank enrollment. Sensitive information is stored securely, with encryption where it applies.\n• Communication preferences: whether you agreed to receive marketing emails or text messages, and when and how.\n• Basic technical information: such as your browser type and pages visited, and whether a marketing email was opened or a link in it was clicked."},{"title":"How we use information","body":"• To respond to your requests and to provide, set up, support and bill for the products and services you choose.\n• To send service messages, such as setup links, reminders, receipts and replies to your questions.\n• To send marketing emails and text messages — only as described here, and you can opt out at any time.\n• To protect our customers and our business, and to meet legal obligations."},{"title":"Text messaging","body":"No mobile information will be shared with third parties or affiliates for marketing or promotional purposes. Information sharing with subcontractors in support services, such as customer service, is permitted. All other categories in this policy exclude text messaging originator opt-in data and consent; this information will not be shared with any third parties.\n\nWe text only people who agreed to receive texts — by checking the optional text consent box on our website forms, or by texting START. Message frequency varies. Message and data rates may apply. Reply HELP for help or STOP to opt out. See our Text Message Terms (link at the bottom of this page)."},{"title":"How we share information","body":"We do not sell your personal information. We share it only with service providers who help us operate — for example the tax software providers and banks you enroll with, secure hosting, email and text message delivery, and payment processing — and only as needed to provide their services; when required by law; or with your permission."},{"title":"How we protect information","body":"We use encryption, access controls, sign-in verification and activity logs to protect your information. We never ask for passwords, Social Security numbers or client tax information by email. No system is perfectly secure, so please contact us right away if you believe your information has been misused."},{"title":"Your choices","body":"• Email: use the unsubscribe link in any marketing email.\n• Text messages: reply STOP to any message, or START to resubscribe.\n• Your information: email info@monarchtaxsuite.com to review, correct or ask us to delete it. Some records must be kept for a period of time by law."},{"title":"Keeping information, children and changes","body":"We keep information as long as needed to provide our services and meet legal record-keeping requirements, then securely delete it. Our website and services are not directed to children under 13. We may update this policy; the effective date at the top shows when it last changed."}]}]', 1, '2026-11-12T00:40:09.970Z');
