INSERT OR IGNORE INTO website_pages (id, site, slug, title, description, nav, hide_nav, position, draft, rev, updated_at) VALUES ('pg-m-text-terms', 'monarch', 'text-terms', 'Text Message Terms', 'Terms for Monarch Tax Suite text messages: what we send, how often, HELP and STOP.', 0, 0, 21, '[{"id":"msec-000o","type":"hero","eyebrow":"Text Message Terms","title":"Text messages from Monarch Tax Suite.","body":"What to expect when you agree to get text messages from us — and how to get help or stop them at any time.\n\nEffective November 12, 2026"},{"id":"msec-000p","type":"cards","tone":"light","columns":2,"items":[{"title":"At a glance","body":"Monarch Tax Suite text messages. Message frequency varies (typically 2–4 messages per month). Message and data rates may apply. Reply HELP for help. Reply STOP to cancel at any time."},{"title":"What we send","body":"Product updates, tax season and onboarding reminders, offers for our software and mentorship, and replies to questions you send us by text."},{"title":"How you sign up","body":"By checking the optional text consent box on one of our website forms (for example our contact form or WISP generator), or by texting START to our number. Agreeing to receive text messages is not a condition of buying any product or service."},{"title":"How to stop","body":"Reply STOP to any message (STOPALL, UNSUBSCRIBE, CANCEL, END and QUIT also work). You’ll get one message confirming you’re unsubscribed, and no more messages after that. To start again, reply START."},{"title":"How to get help","body":"Reply HELP to any message, or email info@monarchtaxsuite.com."},{"title":"Costs and delivery","body":"Message and data rates may apply according to your mobile plan. Carriers are not liable for delayed or undelivered messages."},{"title":"Privacy","body":"No mobile information will be shared with third parties or affiliates for marketing or promotional purposes. Text messaging opt-in data and consent will not be shared with any third parties. Our full Privacy Policy is linked at the bottom of this page."}]}]', 1, '2026-11-12T00:40:09.970Z');
